    /// <summary>The <c>-32600</c> value.</summary>
    public static readonly ErrorCode _32600 = new("-32600");
    /// <summary>The <c>-32601</c> value.</summary>
    public static readonly ErrorCode _32601 = new("-32601");
    /// <summary>The <c>-32602</c> value.</summary>
    public static readonly ErrorCode _32602 = new("-32602");
    /// <summary>The <c>-32603</c> value.</summary>
    public static readonly ErrorCode _32603 = new("-32603");
    /// <summary>The <c>-32800</c> value.</summary>
