}

/// <summary>Resolves <see cref = "RequestPermissionOutcome"/> by its <c>outcome</c> discriminator.</summary>
internal sealed class RequestPermissionOutcomeConverter : JsonConverter<RequestPermissionOutcome>
{
    /// <inheritdoc/>
    public override RequestPermissionOutcome Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("outcome", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "cancelled" => new RequestPermissionOutcomeCancelled
            {
            },
            "selected" => new RequestPermissionOutcomeSelected
            {
                Value = AcpJson.Read<SelectedPermissionOutcome>(root, options)
            },
            _ => new RequestPermissionOutcomeUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, RequestPermissionOutcome value, JsonSerializerOptions options)
    {
        if (value is RequestPermissionOutcomeUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("outcome", value.Discriminator);
        switch (value)
        {
            case RequestPermissionOutcomeCancelled typed:
                break;
            case RequestPermissionOutcomeSelected typed:
                AcpJson.WriteMembers(writer, typed.Value, options);
                break;
            default:
                break;
        }

        writer.WriteEndObject();
    }
}

